#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <algorithm>

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) return 100 + (int)e_; } while (0)
#define CB(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) return 200 + (int)s_; } while (0)

static __device__ __forceinline__ uint32_t pack_h2(float a, float b) {
  __half2 h = __floats2half2_rn(a, b);
  return *reinterpret_cast<uint32_t*>(&h);
}
static __device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

struct K1P {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *gb, *w2, *b2;
  __half *a1, *w1h, *w2h;
  float* sumsq;
  int B, C, H, W, RT, TB, nTW, nTH, nrole, LD, doW2, PS;
  float eps;
};

// Extra blocks of K1: zero the GRN workspace, convert W1 (and W2 + b2' for the scale-h branch) to fp16.
static __device__ void k1_role(const K1P& p, int rb, int tid, int nthr) {
  const int gtid = rb * nthr + tid, gn = p.nrole * nthr;
  const int K4 = 4 * p.C;
  for (int i = gtid; i < p.B * K4; i += gn) p.sumsq[i] = 0.f;
  const long n8 = (long)K4 * p.C / 8;
  for (long i0 = gtid; i0 < n8; i0 += 4L * gn) {
    float4 v[4][2];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      v[u][0] = v[u][1] = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < n8) {
        const float4* s = reinterpret_cast<const float4*>(p.w1 + i * 8);
        v[u][0] = __ldg(s);
        v[u][1] = __ldg(s + 1);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      if (i < n8) {
        uint4 o = make_uint4(pack_h2(v[u][0].x, v[u][0].y), pack_h2(v[u][0].z, v[u][0].w),
                             pack_h2(v[u][1].x, v[u][1].y), pack_h2(v[u][1].z, v[u][1].w));
        *reinterpret_cast<uint4*>(p.w1h + i * 8) = o;
      }
    }
  }
  if (p.doW2) {
    const int nw = nthr / 32, lane = tid & 31;
    const int gw_ = rb * nw + (tid >> 5), gnw = p.nrole * nw;
    for (int c = gw_; c < p.C; c += gnw) {
      const float* wr = p.w2 + (size_t)c * K4;
      __half* o = p.w2h + (size_t)c * p.LD;
      float dot = 0.f;
      for (int k = lane * 4; k < K4; k += 128) {
        float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
        float4 g = __ldg(reinterpret_cast<const float4*>(p.gb + k));
        dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
        *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x, w.y), pack_h2(w.z, w.w));
      }
      dot = warp_sum(dot);
      const float bb = p.b2[c] + dot;
      if (lane < 8) {
        __half hi = __float2half_rn(bb);
        __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
        o[K4 + lane] = v;
      }
    }
  }
}

// Fused depthwise 7x7 conv + bias + LayerNorm. Lane = channel; a tile of RT rows x WT columns of one image
// and all channels per block. Channel chunks of TB planes are staged in shared memory with cp.async.
template <int WT>
__global__ void __launch_bounds__(192) k1_dwln(const K1P p) {
  extern __shared__ float sm[];
  const int tid = threadIdx.x, TB = p.TB;
  if ((int)blockIdx.x < p.nrole) { k1_role(p, blockIdx.x, tid, TB); return; }
  int t = blockIdx.x - p.nrole;
  const int tw = t % p.nTW; t /= p.nTW;
  const int th = t % p.nTH;
  const int b = t / p.nTH;
  const int C = p.C, H = p.H, W = p.W, RT = p.RT, PS = p.PS;
  const int h0 = th * RT, w0 = tw * WT;
  const int rows = min(RT, H - h0);
  constexpr int CW = WT + 6;
  const int RG = (RT + 6) * CW;
  float* pl = sm;
  float* wsm = sm + TB * PS;
  float* dsm = wsm + TB * 49;
  const int lane = tid & 31, warp = tid >> 5;

  for (int ch0 = 0; ch0 < C; ch0 += TB) {
    __syncthreads();
    for (int cl = warp * 32; cl < warp * 32 + 32; ++cl) {
      const float* xp = p.x + (size_t)(b * C + ch0 + cl) * H * W;
      float* dp = pl + cl * PS;
      for (int rem = lane; rem < RG; rem += 32) {
        const int rr = rem / CW, cc = rem - rr * CW;
        const int gh = h0 - 3 + rr, gw = w0 - 3 + cc;
        const bool ok = gh >= 0 && gh < H && gw >= 0 && gw < W;
        const float* src = ok ? xp + gh * W + gw : p.x;
        uint32_t d = (uint32_t)__cvta_generic_to_shared(dp + rem);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;" :: "r"(d), "l"(src), "r"(ok ? 4 : 0));
      }
    }
    for (int e = tid; e < TB * 49; e += TB) {
      uint32_t d = (uint32_t)__cvta_generic_to_shared(wsm + e);
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4;" :: "r"(d), "l"(p.dww + (size_t)ch0 * 49 + e));
    }
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
    __syncthreads();

    float wr[49];
    const float* wp = wsm + tid * 49;
#pragma unroll
    for (int k = 0; k < 49; ++k) wr[k] = wp[k];
    const float bias = __ldg(p.dwb + ch0 + tid);
    const float* pt = pl + tid * PS;
    for (int r = 0; r < rows; ++r) {
      float acc[WT];
#pragma unroll
      for (int w = 0; w < WT; ++w) acc[w] = bias;
#pragma unroll
      for (int i = 0; i < 7; ++i) {
        float xr[CW];
#pragma unroll
        for (int q = 0; q < CW; ++q) xr[q] = pt[(r + i) * CW + q];
#pragma unroll
        for (int j = 0; j < 7; ++j)
#pragma unroll
          for (int w = 0; w < WT; ++w) acc[w] = fmaf(xr[w + j], wr[i * 7 + j], acc[w]);
      }
#pragma unroll
      for (int w = 0; w < WT; ++w) dsm[(r * WT + w) * (C + 1) + ch0 + tid] = acc[w];
    }
  }
  __syncthreads();

  const int nw = TB / 32, ntok = rows * WT;
  for (int tk = warp; tk < ntok; tk += nw) {
    const float* dr = dsm + tk * (C + 1);
    float s = 0.f;
    for (int c = lane; c < C; c += 32) s += dr[c];
    const float mean = warp_sum(s) / C;
    float v = 0.f;
    for (int c = lane; c < C; c += 32) { float d = dr[c] - mean; v += d * d; }
    const float rstd = rsqrtf(warp_sum(v) / C + p.eps);
    const int r = tk / WT, w = tk - r * WT;
    const size_t m = ((size_t)b * H + h0 + r) * W + w0 + w;
    __half* out = p.a1 + m * C;
    for (int pp = lane; pp < C / 2; pp += 32) {
      const int c = 2 * pp;
      float a0 = (dr[c] - mean) * rstd * __ldg(p.lnw + c) + __ldg(p.lnb + c);
      float a1 = (dr[c + 1] - mean) * rstd * __ldg(p.lnw + c + 1) + __ldg(p.lnb + c + 1);
      *reinterpret_cast<uint32_t*>(out + c) = pack_h2(a0, a1);
    }
  }
}

static __device__ __forceinline__ float gelu_erf(float z) {
  return 0.5f * z * (1.f + erff(z * 0.70710678118654752f));
}

// In-place bias + exact GELU on the fp16 GEMM1 output; per-(image, k) sum of squares into sumsq;
// writes the two ones-columns (4C, 4C+1) that carry b2' through GEMM2.
__global__ void k2_gelu(__half* Y, const float* b1, float* sumsq, int HW, int C, int LD, int tokb, int TS) {
  __shared__ float red[5120];
  const int K4 = 4 * C, V = C / 2, Vt = V + 1;
  const int kc = threadIdx.x % Vt, ts = threadIdx.x / Vt;
  const int b = blockIdx.y, t0 = blockIdx.x * tokb, tend = min(t0 + tokb, HW);
  __half* base = Y + (size_t)b * HW * LD;
  float acc[8];
#pragma unroll
  for (int i = 0; i < 8; ++i) acc[i] = 0.f;
  if (kc == V) {
    for (int t = t0 + ts; t < tend; t += TS)
      *reinterpret_cast<uint4*>(base + (size_t)t * LD + K4) = make_uint4(0x3C003C00u, 0u, 0u, 0u);
  } else {
    float bb[8];
    {
      float4 a = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8));
      float4 c = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8 + 4));
      bb[0] = a.x; bb[1] = a.y; bb[2] = a.z; bb[3] = a.w; bb[4] = c.x; bb[5] = c.y; bb[6] = c.z; bb[7] = c.w;
    }
    for (int t = t0 + ts; t < tend; t += 4 * TS) {
      uint4 v[4];
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) v[u] = *reinterpret_cast<const uint4*>(base + (size_t)tt * LD + kc * 8);
      }
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) {
          __half2* hp = reinterpret_cast<__half2*>(&v[u]);
          uint32_t o[4];
#pragma unroll
          for (int q = 0; q < 4; ++q) {
            float2 f = __half22float2(hp[q]);
            float g0 = gelu_erf(f.x + bb[2 * q]), g1 = gelu_erf(f.y + bb[2 * q + 1]);
            acc[2 * q] += g0 * g0;
            acc[2 * q + 1] += g1 * g1;
            o[q] = pack_h2(g0, g1);
          }
          *reinterpret_cast<uint4*>(base + (size_t)tt * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
        }
      }
    }
  }
  if (TS > 1 && kc < V && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
  if (kc < V && ts == 0) {
    for (int q = 1; q < TS; ++q) {
#pragma unroll
      for (int i = 0; i < 8; ++i) acc[i] += red[(q - 1) * K4 + kc * 8 + i];
    }
    float* dst = sumsq + (size_t)b * K4 + kc * 8;
    atomicAdd(reinterpret_cast<float4*>(dst), make_float4(acc[0], acc[1], acc[2], acc[3]));
    atomicAdd(reinterpret_cast<float4*>(dst + 4), make_float4(acc[4], acc[5], acc[6], acc[7]));
  }
}

// s[k] = 1 + gw[k] * gf[k] / (mean_k gf + eps), gf = sqrt(sumsq). 256 threads.
static __device__ void compute_s(float* s, float* red8, const float* ss, const float* gw, int K4, float eps) {
  const int tid = threadIdx.x;
  float loc = 0.f;
  for (int k = tid; k < K4; k += 256) { float g = sqrtf(ss[k]); s[k] = g; loc += g; }
  loc = warp_sum(loc);
  if ((tid & 31) == 0) red8[tid >> 5] = loc;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int i = 0; i < 8; ++i) tot += red8[i];
  const float inv = 1.f / (tot / K4 + eps);
  for (int k = tid; k < K4; k += 256) s[k] = 1.f + __ldg(gw + k) * s[k] * inv;
  __syncthreads();
}

// Branch A: per-image fp16 W2_b = W2 * diag(s_b), with b2' = b2 + W2 gb as hi/lo in columns 4C, 4C+1.
__global__ void __launch_bounds__(256) k3a_w2(const float* w2, const float* gb, const float* b2, const float* gw,
                                              const float* ss, __half* w2s, int C, int LD, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int lane = threadIdx.x & 31, c = blockIdx.x * 8 + (threadIdx.x >> 5);
  if (c >= C) return;
  const float* wr = w2 + (size_t)c * K4;
  __half* o = w2s + ((size_t)b * C + c) * LD;
  float dot = 0.f;
  for (int k = lane * 4; k < K4; k += 128) {
    float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
    float4 g = __ldg(reinterpret_cast<const float4*>(gb + k));
    float4 sv = *reinterpret_cast<const float4*>(sm + k);
    dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
    *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x * sv.x, w.y * sv.y), pack_h2(w.z * sv.z, w.w * sv.w));
  }
  dot = warp_sum(dot);
  const float bb = b2[c] + dot;
  if (lane < 8) {
    __half hi = __float2half_rn(bb);
    __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
    o[K4 + lane] = v;
  }
}

// Branch B: scale the hidden rows in place (columns < 4C), fp16.
__global__ void __launch_bounds__(256) k3b_scale(__half* Y, const float* gw, const float* ss, int HW, int C, int LD,
                                                 int tokb, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, V = C / 2, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int t0 = blockIdx.x * tokb, ntok = min(tokb, HW - t0);
  __half* base = Y + ((size_t)b * HW + t0) * LD;
  const int total = ntok * V;
  for (int i0 = threadIdx.x; i0 < total; i0 += 1024) {
    uint4 v[4];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        v[u] = *reinterpret_cast<const uint4*>(base + (size_t)t * LD + kc * 8);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        __half2* hp = reinterpret_cast<__half2*>(&v[u]);
        uint32_t o[4];
#pragma unroll
        for (int q = 0; q < 4; ++q) {
          float2 f = __half22float2(hp[q]);
          o[q] = pack_h2(f.x * sm[kc * 8 + 2 * q], f.y * sm[kc * 8 + 2 * q + 1]);
        }
        *reinterpret_cast<uint4*>(base + (size_t)t * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
      }
    }
  }
}

// ------------------------------------------------------------------ host side
static const size_t kCublasWs = 32u << 20;

struct Plan {
  int B, C, H, W, M, HW, K4, LD;
  bool bB;
  int WT, TB, RT, nTW, nTH, ntiles, nrole, PS;
  size_t smem1;
  int tokb, TS2, thr2;
  size_t off_a1, off_y, off_w1h, off_w2h, off_ss, off_cw, total;
  cublasLtMatmulDesc_t md1, md2;
  cublasLtMatrixLayout_t la1, lb1, ld1, la2, lb2, lc2;
  cublasLtMatmulHeuristicResult_t h1[8], h2[8];
  int n1, n2;
};

static cublasLtHandle_t g_lt = nullptr;
static std::map<uint64_t, Plan*> g_plans;
static int g_idx1 = 0, g_idx2 = 0;

extern "C" void convblk_set_idx(int a, int b) { g_idx1 = a; g_idx2 = b; }

static size_t al256(size_t x) { return (x + 255) & ~(size_t)255; }

static cublasStatus_t mk_layout(cublasLtMatrixLayout_t* l, cudaDataType t, uint64_t rows, uint64_t cols, int64_t ld,
                                int batch, int64_t stride) {
  cublasStatus_t s = cublasLtMatrixLayoutCreate(l, t, rows, cols, ld);
  if (s != CUBLAS_STATUS_SUCCESS) return s;
  if (batch > 1) {
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &batch, sizeof(batch));
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &stride, sizeof(stride));
  }
  return s;
}

static int heur(cublasLtMatmulDesc_t md, cublasLtMatrixLayout_t a, cublasLtMatrixLayout_t b, cublasLtMatrixLayout_t c,
                uint32_t alA, uint32_t alB, uint32_t alC, cublasLtMatmulHeuristicResult_t* out, int* n) {
  cublasLtMatmulPreference_t pref;
  CB(cublasLtMatmulPreferenceCreate(&pref));
  size_t wsb = kCublasWs;
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsb, sizeof(wsb));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &alA, sizeof(alA));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &alB, sizeof(alB));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &alC, sizeof(alC));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &alC, sizeof(alC));
  int cnt = 0;
  cublasStatus_t s = cublasLtMatmulAlgoGetHeuristic(g_lt, md, a, b, c, c, pref, 8, out, &cnt);
  cublasLtMatmulPreferenceDestroy(pref);
  CB(s);
  if (cnt == 0) return 300;
  *n = cnt;
  return 0;
}

static int make_plan(Plan* P, int B, int C, int H, int W) {
  P->B = B; P->C = C; P->H = H; P->W = W;
  P->HW = H * W; P->M = B * P->HW; P->K4 = 4 * C; P->LD = P->K4 + 8;
  const int M = P->M, HW = P->HW, K4 = P->K4, LD = P->LD;
  P->bB = (size_t)B * C * LD * 2 > ((size_t)16 << 20);
  P->WT = (W % 16 == 0) ? 16 : (W % 14 == 0) ? 14 : (W % 7 == 0) ? 7 : 0;
  if (!P->WT || (C % 32)) return 1;
  int tb = std::min(C, 192) / 32 * 32;
  while (tb >= 32 && C % tb) tb -= 32;
  if (tb < 32) return 2;
  P->TB = tb;
  P->nTW = W / P->WT;
  auto smem_of = [&](int rt) {
    int ps = ((rt + 6) * (P->WT + 6)) | 1;
    return (size_t)4 * ((size_t)tb * ps + (size_t)tb * 49 + (size_t)rt * P->WT * (C + 1));
  };
  int rt = 1;
  for (int r = 1; r <= std::min(H, 8); ++r) {
    int tiles = B * ((H + r - 1) / r) * P->nTW;
    if (smem_of(r) <= 110000 && tiles >= 296) rt = r;
  }
  P->RT = rt;
  P->PS = ((rt + 6) * (P->WT + 6)) | 1;
  P->smem1 = smem_of(rt);
  if (P->smem1 > 227000) return 3;
  P->nTH = (H + rt - 1) / rt;
  P->ntiles = B * P->nTH * P->nTW;
  P->nrole = std::max(64, std::min(128, 148 - P->ntiles));
  if (P->WT == 7) CK(cudaFuncSetAttribute(k1_dwln<7>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 14) CK(cudaFuncSetAttribute(k1_dwln<14>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 16) CK(cudaFuncSetAttribute(k1_dwln<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  int tokb = 4;
  while (tokb * 2 <= 256 && (int64_t)M / (tokb * 2) >= 592) tokb *= 2;
  P->tokb = tokb;
  const int Vt = C / 2 + 1;
  P->TS2 = std::min(4, 1024 / Vt);
  P->thr2 = Vt * P->TS2;
  CK(cudaFuncSetAttribute(k3a_w2, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));
  CK(cudaFuncSetAttribute(k3b_scale, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));

  P->off_a1 = 0;
  P->off_y = al256((size_t)M * C * 2);
  P->off_w1h = P->off_y + al256((size_t)M * LD * 2);
  P->off_w2h = P->off_w1h + al256((size_t)K4 * C * 2);
  P->off_ss = P->off_w2h + al256((size_t)(P->bB ? 1 : B) * C * LD * 2);
  P->off_cw = P->off_ss + al256((size_t)B * K4 * 4);
  P->total = P->off_cw + kCublasWs;

  if (!g_lt) CB(cublasLtCreate(&g_lt));
  cublasOperation_t opT = CUBLAS_OP_T, opN = CUBLAS_OP_N;
  CB(cublasLtMatmulDescCreate(&P->md1, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la1, CUDA_R_16F, C, K4, C, 1, 0));
  CB(mk_layout(&P->lb1, CUDA_R_16F, C, M, C, 1, 0));
  CB(mk_layout(&P->ld1, CUDA_R_16F, K4, M, LD, 1, 0));
  int rc = heur(P->md1, P->la1, P->lb1, P->ld1, 16, 16, 16, P->h1, &P->n1);
  if (rc) return rc;

  CB(cublasLtMatmulDescCreate(&P->md2, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la2, CUDA_R_16F, LD, HW, LD, B, (int64_t)HW * LD));
  CB(mk_layout(&P->lb2, CUDA_R_16F, LD, C, LD, B, P->bB ? 0 : (int64_t)C * LD));
  CB(mk_layout(&P->lc2, CUDA_R_32F, HW, C, HW, B, (int64_t)C * HW));
  rc = heur(P->md2, P->la2, P->lb2, P->lc2, 16, 16, (HW % 4 == 0) ? 16 : 4, P->h2, &P->n2);
  return rc;
}

static Plan* get_plan(int B, int C, int H, int W, int* err) {
  uint64_t key = ((uint64_t)B << 48) ^ ((uint64_t)C << 32) ^ ((uint64_t)H << 16) ^ (uint64_t)W;
  auto it = g_plans.find(key);
  if (it != g_plans.end()) return it->second;
  Plan* P = new Plan();
  int rc = make_plan(P, B, C, H, W);
  if (rc) { *err = rc; delete P; return nullptr; }
  g_plans[key] = P;
  return P;
}

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  return P ? P->total : 0;
}

extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* wsp, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  if (!P) return err;
  char* ws = static_cast<char*>(wsp);
  __half* a1 = reinterpret_cast<__half*>(ws + P->off_a1);
  __half* y = reinterpret_cast<__half*>(ws + P->off_y);
  __half* w1h = reinterpret_cast<__half*>(ws + P->off_w1h);
  __half* w2h = reinterpret_cast<__half*>(ws + P->off_w2h);
  float* ss = reinterpret_cast<float*>(ws + P->off_ss);
  void* cw = ws + P->off_cw;

  K1P k;
  k.x = x; k.dww = dww; k.dwb = dwb; k.lnw = lnw; k.lnb = lnb; k.w1 = w1; k.gb = gb; k.w2 = w2; k.b2 = b2;
  k.a1 = a1; k.w1h = w1h; k.w2h = w2h; k.sumsq = ss;
  k.B = B; k.C = C; k.H = H; k.W = W; k.RT = P->RT; k.TB = P->TB; k.nTW = P->nTW; k.nTH = P->nTH;
  k.nrole = P->nrole; k.LD = P->LD; k.doW2 = P->bB ? 1 : 0; k.PS = P->PS; k.eps = ln_eps;
  const int g1 = P->nrole + P->ntiles;
  if (P->WT == 7) k1_dwln<7><<<g1, P->TB, P->smem1, st>>>(k);
  else if (P->WT == 14) k1_dwln<14><<<g1, P->TB, P->smem1, st>>>(k);
  else k1_dwln<16><<<g1, P->TB, P->smem1, st>>>(k);
  CK(cudaGetLastError());

  const float alpha = 1.f, beta0 = 0.f, beta1 = 1.f;
  const int i1 = std::min(g_idx1, P->n1 - 1), i2 = std::min(g_idx2, P->n2 - 1);
  CB(cublasLtMatmul(g_lt, P->md1, &alpha, w1h, P->la1, a1, P->lb1, &beta0, y, P->ld1, y, P->ld1, &P->h1[i1].algo, cw,
                    kCublasWs, st));

  const int nb = (P->HW + P->tokb - 1) / P->tokb;
  k2_gelu<<<dim3(nb, B), P->thr2, 0, st>>>(y, b1, ss, P->HW, C, P->LD, P->tokb, P->TS2);
  CK(cudaGetLastError());
  if (P->bB) {
    k3b_scale<<<dim3(nb, B), 256, 4 * P->K4 + 64, st>>>(y, gw, ss, P->HW, C, P->LD, P->tokb, grn_eps);
  } else {
    k3a_w2<<<dim3((C + 7) / 8, B), 256, 4 * P->K4 + 64, st>>>(w2, gb, b2, gw, ss, w2h, C, P->LD, grn_eps);
  }
  CK(cudaGetLastError());

  CB(cublasLtMatmul(g_lt, P->md2, &alpha, y, P->la2, w2h, P->lb2, &beta1, x, P->lc2, out, P->lc2, &P->h2[i2].algo, cw,
                    kCublasWs, st));
  return 0;
}

#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W);
extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* ws, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st);

void run(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb,
         torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2,
         double eps, double ln_eps, torch::Tensor out) {
  c10::cuda::CUDAGuard guard(x.device());
  TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32 && x.is_contiguous(), "x must be contiguous fp32 cuda");
  const int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
  size_t wb = convblk_ws_bytes(B, C, H, W);
  TORCH_CHECK(wb > 0, "unsupported shape or cuBLASLt heuristic failure");
  auto ws = torch::empty({(int64_t)wb}, x.options().dtype(torch::kUInt8));
  cudaStream_t st = c10::cuda::getCurrentCUDAStream();
  int rc = convblk_run(x.data_ptr<float>(), dww.data_ptr<float>(), dwb.data_ptr<float>(), lnw.data_ptr<float>(),
                       lnb.data_ptr<float>(), w1.data_ptr<float>(), b1.data_ptr<float>(), gw.data_ptr<float>(),
                       gb.data_ptr<float>(), w2.data_ptr<float>(), b2.data_ptr<float>(), out.data_ptr<float>(),
                       ws.data_ptr(), B, C, H, W, (float)eps, (float)ln_eps, st);
  TORCH_CHECK(rc == 0, "convblk_run failed with code ", rc);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "convnextv2 block"); }

#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <algorithm>

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) return 100 + (int)e_; } while (0)
#define CB(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) return 200 + (int)s_; } while (0)

static __device__ __forceinline__ uint32_t pack_h2(float a, float b) {
  __half2 h = __floats2half2_rn(a, b);
  return *reinterpret_cast<uint32_t*>(&h);
}
static __device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

struct K1P {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *gb, *w2, *b2;
  __half *a1, *w1h, *w2h;
  float* sumsq;
  int B, C, H, W, RT, TB, nTW, nTH, nrole, LD, doW2, PS;
  float eps;
};

// Extra blocks of K1: zero the GRN workspace, convert W1 (and W2 + b2' for the scale-h branch) to fp16.
static __device__ void k1_role(const K1P& p, int rb, int tid, int nthr) {
  const int gtid = rb * nthr + tid, gn = p.nrole * nthr;
  const int K4 = 4 * p.C;
  for (int i = gtid; i < p.B * K4; i += gn) p.sumsq[i] = 0.f;
  const long n8 = (long)K4 * p.C / 8;
  for (long i0 = gtid; i0 < n8; i0 += 4L * gn) {
    float4 v[4][2];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      v[u][0] = v[u][1] = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < n8) {
        const float4* s = reinterpret_cast<const float4*>(p.w1 + i * 8);
        v[u][0] = __ldg(s);
        v[u][1] = __ldg(s + 1);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      if (i < n8) {
        uint4 o = make_uint4(pack_h2(v[u][0].x, v[u][0].y), pack_h2(v[u][0].z, v[u][0].w),
                             pack_h2(v[u][1].x, v[u][1].y), pack_h2(v[u][1].z, v[u][1].w));
        *reinterpret_cast<uint4*>(p.w1h + i * 8) = o;
      }
    }
  }
  if (p.doW2) {
    const int nw = nthr / 32, lane = tid & 31;
    const int gw_ = rb * nw + (tid >> 5), gnw = p.nrole * nw;
    for (int c = gw_; c < p.C; c += gnw) {
      const float* wr = p.w2 + (size_t)c * K4;
      __half* o = p.w2h + (size_t)c * p.LD;
      float dot = 0.f;
      for (int k = lane * 4; k < K4; k += 128) {
        float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
        float4 g = __ldg(reinterpret_cast<const float4*>(p.gb + k));
        dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
        *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x, w.y), pack_h2(w.z, w.w));
      }
      dot = warp_sum(dot);
      const float bb = p.b2[c] + dot;
      if (lane < 8) {
        __half hi = __float2half_rn(bb);
        __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
        o[K4 + lane] = v;
      }
    }
  }
}

// Fused depthwise 7x7 conv + bias + LayerNorm. Lane = channel; a tile of RT rows x WT columns of one image
// and all channels per block. Channel chunks of TB planes are staged in shared memory with cp.async.
template <int WT>
__global__ void __launch_bounds__(192) k1_dwln(const K1P p) {
  extern __shared__ float sm[];
  const int tid = threadIdx.x, TB = p.TB;
  if ((int)blockIdx.x < p.nrole) { k1_role(p, blockIdx.x, tid, TB); return; }
  int t = blockIdx.x - p.nrole;
  const int tw = t % p.nTW; t /= p.nTW;
  const int th = t % p.nTH;
  const int b = t / p.nTH;
  const int C = p.C, H = p.H, W = p.W, RT = p.RT, PS = p.PS;
  const int h0 = th * RT, w0 = tw * WT;
  const int rows = min(RT, H - h0);
  constexpr int CW = WT + 6;
  const int RG = (RT + 6) * CW;
  float* pl = sm;
  float* wsm = sm + TB * PS;
  float* dsm = wsm + TB * 49;
  const int lane = tid & 31, warp = tid >> 5;

  for (int ch0 = 0; ch0 < C; ch0 += TB) {
    __syncthreads();
    for (int cl = warp * 32; cl < warp * 32 + 32; ++cl) {
      const float* xp = p.x + (size_t)(b * C + ch0 + cl) * H * W;
      float* dp = pl + cl * PS;
      for (int rem = lane; rem < RG; rem += 32) {
        const int rr = rem / CW, cc = rem - rr * CW;
        const int gh = h0 - 3 + rr, gw = w0 - 3 + cc;
        const bool ok = gh >= 0 && gh < H && gw >= 0 && gw < W;
        const float* src = ok ? xp + gh * W + gw : p.x;
        uint32_t d = (uint32_t)__cvta_generic_to_shared(dp + rem);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;" :: "r"(d), "l"(src), "r"(ok ? 4 : 0));
      }
    }
    for (int e = tid; e < TB * 49; e += TB) {
      uint32_t d = (uint32_t)__cvta_generic_to_shared(wsm + e);
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4;" :: "r"(d), "l"(p.dww + (size_t)ch0 * 49 + e));
    }
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
    __syncthreads();

    float wr[49];
    const float* wp = wsm + tid * 49;
#pragma unroll
    for (int k = 0; k < 49; ++k) wr[k] = wp[k];
    const float bias = __ldg(p.dwb + ch0 + tid);
    const float* pt = pl + tid * PS;
    for (int r = 0; r < rows; ++r) {
      float acc[WT];
#pragma unroll
      for (int w = 0; w < WT; ++w) acc[w] = bias;
#pragma unroll
      for (int i = 0; i < 7; ++i) {
        float xr[CW];
#pragma unroll
        for (int q = 0; q < CW; ++q) xr[q] = pt[(r + i) * CW + q];
#pragma unroll
        for (int j = 0; j < 7; ++j)
#pragma unroll
          for (int w = 0; w < WT; ++w) acc[w] = fmaf(xr[w + j], wr[i * 7 + j], acc[w]);
      }
#pragma unroll
      for (int w = 0; w < WT; ++w) dsm[(r * WT + w) * (C + 1) + ch0 + tid] = acc[w];
    }
  }
  __syncthreads();

  const int nw = TB / 32, ntok = rows * WT;
  for (int tk = warp; tk < ntok; tk += nw) {
    const float* dr = dsm + tk * (C + 1);
    float s = 0.f;
    for (int c = lane; c < C; c += 32) s += dr[c];
    const float mean = warp_sum(s) / C;
    float v = 0.f;
    for (int c = lane; c < C; c += 32) { float d = dr[c] - mean; v += d * d; }
    const float rstd = rsqrtf(warp_sum(v) / C + p.eps);
    const int r = tk / WT, w = tk - r * WT;
    const size_t m = ((size_t)b * H + h0 + r) * W + w0 + w;
    __half* out = p.a1 + m * C;
    for (int pp = lane; pp < C / 2; pp += 32) {
      const int c = 2 * pp;
      float a0 = (dr[c] - mean) * rstd * __ldg(p.lnw + c) + __ldg(p.lnb + c);
      float a1 = (dr[c + 1] - mean) * rstd * __ldg(p.lnw + c + 1) + __ldg(p.lnb + c + 1);
      *reinterpret_cast<uint32_t*>(out + c) = pack_h2(a0, a1);
    }
  }
}

static __device__ __forceinline__ float gelu_erf(float z) {
  return 0.5f * z * (1.f + erff(z * 0.70710678118654752f));
}

// In-place bias + exact GELU on the fp16 GEMM1 output; per-(image, k) sum of squares into sumsq;
// writes the two ones-columns (4C, 4C+1) that carry b2' through GEMM2.
__global__ void k2_gelu(__half* Y, const float* b1, float* sumsq, int HW, int C, int LD, int tokb, int TS) {
  __shared__ float red[5120];
  const int K4 = 4 * C, V = C / 2, Vt = V + 1;
  const int kc = threadIdx.x % Vt, ts = threadIdx.x / Vt;
  const int b = blockIdx.y, t0 = blockIdx.x * tokb, tend = min(t0 + tokb, HW);
  __half* base = Y + (size_t)b * HW * LD;
  float acc[8];
#pragma unroll
  for (int i = 0; i < 8; ++i) acc[i] = 0.f;
  if (kc == V) {
    for (int t = t0 + ts; t < tend; t += TS)
      *reinterpret_cast<uint4*>(base + (size_t)t * LD + K4) = make_uint4(0x3C003C00u, 0u, 0u, 0u);
  } else {
    float bb[8];
    {
      float4 a = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8));
      float4 c = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8 + 4));
      bb[0] = a.x; bb[1] = a.y; bb[2] = a.z; bb[3] = a.w; bb[4] = c.x; bb[5] = c.y; bb[6] = c.z; bb[7] = c.w;
    }
    for (int t = t0 + ts; t < tend; t += 4 * TS) {
      uint4 v[4];
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) v[u] = *reinterpret_cast<const uint4*>(base + (size_t)tt * LD + kc * 8);
      }
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) {
          __half2* hp = reinterpret_cast<__half2*>(&v[u]);
          uint32_t o[4];
#pragma unroll
          for (int q = 0; q < 4; ++q) {
            float2 f = __half22float2(hp[q]);
            float g0 = gelu_erf(f.x + bb[2 * q]), g1 = gelu_erf(f.y + bb[2 * q + 1]);
            acc[2 * q] += g0 * g0;
            acc[2 * q + 1] += g1 * g1;
            o[q] = pack_h2(g0, g1);
          }
          *reinterpret_cast<uint4*>(base + (size_t)tt * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
        }
      }
    }
  }
  if (TS > 1 && kc < V && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
  if (kc < V && ts == 0) {
    for (int q = 1; q < TS; ++q) {
#pragma unroll
      for (int i = 0; i < 8; ++i) acc[i] += red[(q - 1) * K4 + kc * 8 + i];
    }
    float* dst = sumsq + (size_t)b * K4 + kc * 8;
    atomicAdd(reinterpret_cast<float4*>(dst), make_float4(acc[0], acc[1], acc[2], acc[3]));
    atomicAdd(reinterpret_cast<float4*>(dst + 4), make_float4(acc[4], acc[5], acc[6], acc[7]));
  }
}

// s[k] = 1 + gw[k] * gf[k] / (mean_k gf + eps), gf = sqrt(sumsq). 256 threads.
static __device__ void compute_s(float* s, float* red8, const float* ss, const float* gw, int K4, float eps) {
  const int tid = threadIdx.x;
  float loc = 0.f;
  for (int k = tid; k < K4; k += 256) { float g = sqrtf(ss[k]); s[k] = g; loc += g; }
  loc = warp_sum(loc);
  if ((tid & 31) == 0) red8[tid >> 5] = loc;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int i = 0; i < 8; ++i) tot += red8[i];
  const float inv = 1.f / (tot / K4 + eps);
  for (int k = tid; k < K4; k += 256) s[k] = 1.f + __ldg(gw + k) * s[k] * inv;
  __syncthreads();
}

// Branch A: per-image fp16 W2_b = W2 * diag(s_b), with b2' = b2 + W2 gb as hi/lo in columns 4C, 4C+1.
__global__ void __launch_bounds__(256) k3a_w2(const float* w2, const float* gb, const float* b2, const float* gw,
                                              const float* ss, __half* w2s, int C, int LD, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int lane = threadIdx.x & 31, c = blockIdx.x * 8 + (threadIdx.x >> 5);
  if (c >= C) return;
  const float* wr = w2 + (size_t)c * K4;
  __half* o = w2s + ((size_t)b * C + c) * LD;
  float dot = 0.f;
  for (int k = lane * 4; k < K4; k += 128) {
    float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
    float4 g = __ldg(reinterpret_cast<const float4*>(gb + k));
    float4 sv = *reinterpret_cast<const float4*>(sm + k);
    dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
    *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x * sv.x, w.y * sv.y), pack_h2(w.z * sv.z, w.w * sv.w));
  }
  dot = warp_sum(dot);
  const float bb = b2[c] + dot;
  if (lane < 8) {
    __half hi = __float2half_rn(bb);
    __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
    o[K4 + lane] = v;
  }
}

// Branch B: scale the hidden rows in place (columns < 4C), fp16.
__global__ void __launch_bounds__(256) k3b_scale(__half* Y, const float* gw, const float* ss, int HW, int C, int LD,
                                                 int tokb, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, V = C / 2, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int t0 = blockIdx.x * tokb, ntok = min(tokb, HW - t0);
  __half* base = Y + ((size_t)b * HW + t0) * LD;
  const int total = ntok * V;
  for (int i0 = threadIdx.x; i0 < total; i0 += 1024) {
    uint4 v[4];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        v[u] = *reinterpret_cast<const uint4*>(base + (size_t)t * LD + kc * 8);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        __half2* hp = reinterpret_cast<__half2*>(&v[u]);
        uint32_t o[4];
#pragma unroll
        for (int q = 0; q < 4; ++q) {
          float2 f = __half22float2(hp[q]);
          o[q] = pack_h2(f.x * sm[kc * 8 + 2 * q], f.y * sm[kc * 8 + 2 * q + 1]);
        }
        *reinterpret_cast<uint4*>(base + (size_t)t * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
      }
    }
  }
}

// ------------------------------------------------------------------ host side
static const size_t kCublasWs = 32u << 20;

struct Plan {
  int B, C, H, W, M, HW, K4, LD;
  bool bB;
  int WT, TB, RT, nTW, nTH, ntiles, nrole, PS;
  size_t smem1;
  int tokb, TS2, thr2;
  size_t off_a1, off_y, off_w1h, off_w2h, off_ss, off_cw, total;
  cublasLtMatmulDesc_t md1, md2;
  cublasLtMatrixLayout_t la1, lb1, ld1, la2, lb2, lc2;
  cublasLtMatmulHeuristicResult_t h1[8], h2[8];
  int n1, n2;
};

static cublasLtHandle_t g_lt = nullptr;
static std::map<uint64_t, Plan*> g_plans;
static int g_idx1 = 0, g_idx2 = 0;

extern "C" void convblk_set_idx(int a, int b) { g_idx1 = a; g_idx2 = b; }

static size_t al256(size_t x) { return (x + 255) & ~(size_t)255; }

static cublasStatus_t mk_layout(cublasLtMatrixLayout_t* l, cudaDataType t, uint64_t rows, uint64_t cols, int64_t ld,
                                int batch, int64_t stride) {
  cublasStatus_t s = cublasLtMatrixLayoutCreate(l, t, rows, cols, ld);
  if (s != CUBLAS_STATUS_SUCCESS) return s;
  if (batch > 1) {
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &batch, sizeof(batch));
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &stride, sizeof(stride));
  }
  return s;
}

static int heur(cublasLtMatmulDesc_t md, cublasLtMatrixLayout_t a, cublasLtMatrixLayout_t b, cublasLtMatrixLayout_t c,
                uint32_t alA, uint32_t alB, uint32_t alC, cublasLtMatmulHeuristicResult_t* out, int* n) {
  cublasLtMatmulPreference_t pref;
  CB(cublasLtMatmulPreferenceCreate(&pref));
  size_t wsb = kCublasWs;
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsb, sizeof(wsb));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &alA, sizeof(alA));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &alB, sizeof(alB));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &alC, sizeof(alC));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &alC, sizeof(alC));
  int cnt = 0;
  cublasStatus_t s = cublasLtMatmulAlgoGetHeuristic(g_lt, md, a, b, c, c, pref, 8, out, &cnt);
  cublasLtMatmulPreferenceDestroy(pref);
  CB(s);
  if (cnt == 0) return 300;
  *n = cnt;
  return 0;
}

static int make_plan(Plan* P, int B, int C, int H, int W) {
  P->B = B; P->C = C; P->H = H; P->W = W;
  P->HW = H * W; P->M = B * P->HW; P->K4 = 4 * C; P->LD = P->K4 + 8;
  const int M = P->M, HW = P->HW, K4 = P->K4, LD = P->LD;
  P->bB = (size_t)B * C * LD * 2 > ((size_t)16 << 20);
  P->WT = (W % 16 == 0) ? 16 : (W % 14 == 0) ? 14 : (W % 7 == 0) ? 7 : 0;
  if (!P->WT || (C % 32)) return 1;
  int tb = std::min(C, 192) / 32 * 32;
  while (tb >= 32 && C % tb) tb -= 32;
  if (tb < 32) return 2;
  P->TB = tb;
  P->nTW = W / P->WT;
  auto smem_of = [&](int rt) {
    int ps = ((rt + 6) * (P->WT + 6)) | 1;
    return (size_t)4 * ((size_t)tb * ps + (size_t)tb * 49 + (size_t)rt * P->WT * (C + 1));
  };
  int rt = 1;
  for (int r = 1; r <= std::min(H, 8); ++r) {
    int tiles = B * ((H + r - 1) / r) * P->nTW;
    if (smem_of(r) <= 110000 && tiles >= 296) rt = r;
  }
  P->RT = rt;
  P->PS = ((rt + 6) * (P->WT + 6)) | 1;
  P->smem1 = smem_of(rt);
  if (P->smem1 > 227000) return 3;
  P->nTH = (H + rt - 1) / rt;
  P->ntiles = B * P->nTH * P->nTW;
  P->nrole = std::max(64, std::min(128, 148 - P->ntiles));
  if (P->WT == 7) CK(cudaFuncSetAttribute(k1_dwln<7>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 14) CK(cudaFuncSetAttribute(k1_dwln<14>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 16) CK(cudaFuncSetAttribute(k1_dwln<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  int tokb = 4;
  while (tokb * 2 <= 256 && (int64_t)M / (tokb * 2) >= 592) tokb *= 2;
  P->tokb = tokb;
  const int Vt = C / 2 + 1;
  P->TS2 = std::min(4, 1024 / Vt);
  P->thr2 = Vt * P->TS2;
  CK(cudaFuncSetAttribute(k3a_w2, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));
  CK(cudaFuncSetAttribute(k3b_scale, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));

  P->off_a1 = 0;
  P->off_y = al256((size_t)M * C * 2);
  P->off_w1h = P->off_y + al256((size_t)M * LD * 2);
  P->off_w2h = P->off_w1h + al256((size_t)K4 * C * 2);
  P->off_ss = P->off_w2h + al256((size_t)(P->bB ? 1 : B) * C * LD * 2);
  P->off_cw = P->off_ss + al256((size_t)B * K4 * 4);
  P->total = P->off_cw + kCublasWs;

  if (!g_lt) CB(cublasLtCreate(&g_lt));
  cublasOperation_t opT = CUBLAS_OP_T, opN = CUBLAS_OP_N;
  CB(cublasLtMatmulDescCreate(&P->md1, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la1, CUDA_R_16F, C, K4, C, 1, 0));
  CB(mk_layout(&P->lb1, CUDA_R_16F, C, M, C, 1, 0));
  CB(mk_layout(&P->ld1, CUDA_R_16F, K4, M, LD, 1, 0));
  int rc = heur(P->md1, P->la1, P->lb1, P->ld1, 16, 16, 16, P->h1, &P->n1);
  if (rc) return rc;

  CB(cublasLtMatmulDescCreate(&P->md2, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la2, CUDA_R_16F, LD, HW, LD, B, (int64_t)HW * LD));
  CB(mk_layout(&P->lb2, CUDA_R_16F, LD, C, LD, B, P->bB ? 0 : (int64_t)C * LD));
  CB(mk_layout(&P->lc2, CUDA_R_32F, HW, C, HW, B, (int64_t)C * HW));
  rc = heur(P->md2, P->la2, P->lb2, P->lc2, 16, 16, (HW % 4 == 0) ? 16 : 4, P->h2, &P->n2);
  return rc;
}

static Plan* get_plan(int B, int C, int H, int W, int* err) {
  uint64_t key = ((uint64_t)B << 48) ^ ((uint64_t)C << 32) ^ ((uint64_t)H << 16) ^ (uint64_t)W;
  auto it = g_plans.find(key);
  if (it != g_plans.end()) return it->second;
  Plan* P = new Plan();
  int rc = make_plan(P, B, C, H, W);
  if (rc) { *err = rc; delete P; return nullptr; }
  g_plans[key] = P;
  return P;
}

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  return P ? P->total : 0;
}

extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* wsp, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  if (!P) return err;
  char* ws = static_cast<char*>(wsp);
  __half* a1 = reinterpret_cast<__half*>(ws + P->off_a1);
  __half* y = reinterpret_cast<__half*>(ws + P->off_y);
  __half* w1h = reinterpret_cast<__half*>(ws + P->off_w1h);
  __half* w2h = reinterpret_cast<__half*>(ws + P->off_w2h);
  float* ss = reinterpret_cast<float*>(ws + P->off_ss);
  void* cw = ws + P->off_cw;

  K1P k;
  k.x = x; k.dww = dww; k.dwb = dwb; k.lnw = lnw; k.lnb = lnb; k.w1 = w1; k.gb = gb; k.w2 = w2; k.b2 = b2;
  k.a1 = a1; k.w1h = w1h; k.w2h = w2h; k.sumsq = ss;
  k.B = B; k.C = C; k.H = H; k.W = W; k.RT = P->RT; k.TB = P->TB; k.nTW = P->nTW; k.nTH = P->nTH;
  k.nrole = P->nrole; k.LD = P->LD; k.doW2 = P->bB ? 1 : 0; k.PS = P->PS; k.eps = ln_eps;
  const int g1 = P->nrole + P->ntiles;
  if (P->WT == 7) k1_dwln<7><<<g1, P->TB, P->smem1, st>>>(k);
  else if (P->WT == 14) k1_dwln<14><<<g1, P->TB, P->smem1, st>>>(k);
  else k1_dwln<16><<<g1, P->TB, P->smem1, st>>>(k);
  CK(cudaGetLastError());

  const float alpha = 1.f, beta0 = 0.f, beta1 = 1.f;
  const int i1 = std::min(g_idx1, P->n1 - 1), i2 = std::min(g_idx2, P->n2 - 1);
  CB(cublasLtMatmul(g_lt, P->md1, &alpha, w1h, P->la1, a1, P->lb1, &beta0, y, P->ld1, y, P->ld1, &P->h1[i1].algo, cw,
                    kCublasWs, st));

  const int nb = (P->HW + P->tokb - 1) / P->tokb;
  k2_gelu<<<dim3(nb, B), P->thr2, 0, st>>>(y, b1, ss, P->HW, C, P->LD, P->tokb, P->TS2);
  CK(cudaGetLastError());
  if (P->bB) {
    k3b_scale<<<dim3(nb, B), 256, 4 * P->K4 + 64, st>>>(y, gw, ss, P->HW, C, P->LD, P->tokb, grn_eps);
  } else {
    k3a_w2<<<dim3((C + 7) / 8, B), 256, 4 * P->K4 + 64, st>>>(w2, gb, b2, gw, ss, w2h, C, P->LD, grn_eps);
  }
  CK(cudaGetLastError());

  CB(cublasLtMatmul(g_lt, P->md2, &alpha, y, P->la2, w2h, P->lb2, &beta1, x, P->lc2, out, P->lc2, &P->h2[i2].algo, cw,
                    kCublasWs, st));
  return 0;
}

#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W);
extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* ws, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st);

void run(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb,
         torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2,
         double eps, double ln_eps, torch::Tensor out) {
  c10::cuda::CUDAGuard guard(x.device());
  TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32 && x.is_contiguous(), "x must be contiguous fp32 cuda");
  const int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
  size_t wb = convblk_ws_bytes(B, C, H, W);
  TORCH_CHECK(wb > 0, "unsupported shape or cuBLASLt heuristic failure");
  auto ws = torch::empty({(int64_t)wb}, x.options().dtype(torch::kUInt8));
  cudaStream_t st = c10::cuda::getCurrentCUDAStream();
  int rc = convblk_run(x.data_ptr<float>(), dww.data_ptr<float>(), dwb.data_ptr<float>(), lnw.data_ptr<float>(),
                       lnb.data_ptr<float>(), w1.data_ptr<float>(), b1.data_ptr<float>(), gw.data_ptr<float>(),
                       gb.data_ptr<float>(), w2.data_ptr<float>(), b2.data_ptr<float>(), out.data_ptr<float>(),
                       ws.data_ptr(), B, C, H, W, (float)eps, (float)ln_eps, st);
  TORCH_CHECK(rc == 0, "convblk_run failed with code ", rc);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "convnextv2 block"); }

#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <algorithm>

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) return 100 + (int)e_; } while (0)
#define CB(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) return 200 + (int)s_; } while (0)

static __device__ __forceinline__ uint32_t pack_h2(float a, float b) {
  __half2 h = __floats2half2_rn(a, b);
  return *reinterpret_cast<uint32_t*>(&h);
}
static __device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

struct K1P {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *gb, *w2, *b2;
  __half *a1, *w1h, *w2h;
  float* sumsq;
  int B, C, H, W, RT, TB, nTW, nTH, nrole, LD, doW2, PS;
  float eps;
};

// Extra blocks of K1: zero the GRN workspace, convert W1 (and W2 + b2' for the scale-h branch) to fp16.
static __device__ void k1_role(const K1P& p, int rb, int tid, int nthr) {
  const int gtid = rb * nthr + tid, gn = p.nrole * nthr;
  const int K4 = 4 * p.C;
  for (int i = gtid; i < p.B * K4; i += gn) p.sumsq[i] = 0.f;
  const long n8 = (long)K4 * p.C / 8;
  for (long i0 = gtid; i0 < n8; i0 += 4L * gn) {
    float4 v[4][2];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      v[u][0] = v[u][1] = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < n8) {
        const float4* s = reinterpret_cast<const float4*>(p.w1 + i * 8);
        v[u][0] = __ldg(s);
        v[u][1] = __ldg(s + 1);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      if (i < n8) {
        uint4 o = make_uint4(pack_h2(v[u][0].x, v[u][0].y), pack_h2(v[u][0].z, v[u][0].w),
                             pack_h2(v[u][1].x, v[u][1].y), pack_h2(v[u][1].z, v[u][1].w));
        *reinterpret_cast<uint4*>(p.w1h + i * 8) = o;
      }
    }
  }
  if (p.doW2) {
    const int nw = nthr / 32, lane = tid & 31;
    const int gw_ = rb * nw + (tid >> 5), gnw = p.nrole * nw;
    for (int c = gw_; c < p.C; c += gnw) {
      const float* wr = p.w2 + (size_t)c * K4;
      __half* o = p.w2h + (size_t)c * p.LD;
      float dot = 0.f;
      for (int k = lane * 4; k < K4; k += 128) {
        float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
        float4 g = __ldg(reinterpret_cast<const float4*>(p.gb + k));
        dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
        *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x, w.y), pack_h2(w.z, w.w));
      }
      dot = warp_sum(dot);
      const float bb = p.b2[c] + dot;
      if (lane < 8) {
        __half hi = __float2half_rn(bb);
        __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
        o[K4 + lane] = v;
      }
    }
  }
}

// Fused depthwise 7x7 conv + bias + LayerNorm. Lane = channel; a tile of RT rows x WT columns of one image
// and all channels per block. Channel chunks of TB planes are staged in shared memory with cp.async.
template <int WT>
__global__ void __launch_bounds__(192) k1_dwln(const K1P p) {
  extern __shared__ float sm[];
  const int tid = threadIdx.x, TB = p.TB;
  if ((int)blockIdx.x < p.nrole) { k1_role(p, blockIdx.x, tid, TB); return; }
  int t = blockIdx.x - p.nrole;
  const int tw = t % p.nTW; t /= p.nTW;
  const int th = t % p.nTH;
  const int b = t / p.nTH;
  const int C = p.C, H = p.H, W = p.W, RT = p.RT, PS = p.PS;
  const int h0 = th * RT, w0 = tw * WT;
  const int rows = min(RT, H - h0);
  constexpr int CW = WT + 6;
  const int RG = (RT + 6) * CW;
  float* pl = sm;
  float* wsm = sm + TB * PS;
  float* dsm = wsm + TB * 49;
  const int lane = tid & 31, warp = tid >> 5;

  for (int ch0 = 0; ch0 < C; ch0 += TB) {
    __syncthreads();
    for (int cl = warp * 32; cl < warp * 32 + 32; ++cl) {
      const float* xp = p.x + (size_t)(b * C + ch0 + cl) * H * W;
      float* dp = pl + cl * PS;
      for (int rem = lane; rem < RG; rem += 32) {
        const int rr = rem / CW, cc = rem - rr * CW;
        const int gh = h0 - 3 + rr, gw = w0 - 3 + cc;
        const bool ok = gh >= 0 && gh < H && gw >= 0 && gw < W;
        const float* src = ok ? xp + gh * W + gw : p.x;
        uint32_t d = (uint32_t)__cvta_generic_to_shared(dp + rem);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;" :: "r"(d), "l"(src), "r"(ok ? 4 : 0));
      }
    }
    for (int e = tid; e < TB * 49; e += TB) {
      uint32_t d = (uint32_t)__cvta_generic_to_shared(wsm + e);
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4;" :: "r"(d), "l"(p.dww + (size_t)ch0 * 49 + e));
    }
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
    __syncthreads();

    float wr[49];
    const float* wp = wsm + tid * 49;
#pragma unroll
    for (int k = 0; k < 49; ++k) wr[k] = wp[k];
    const float bias = __ldg(p.dwb + ch0 + tid);
    const float* pt = pl + tid * PS;
    for (int r = 0; r < rows; ++r) {
      float acc[WT];
#pragma unroll
      for (int w = 0; w < WT; ++w) acc[w] = bias;
#pragma unroll
      for (int i = 0; i < 7; ++i) {
        float xr[CW];
#pragma unroll
        for (int q = 0; q < CW; ++q) xr[q] = pt[(r + i) * CW + q];
#pragma unroll
        for (int j = 0; j < 7; ++j)
#pragma unroll
          for (int w = 0; w < WT; ++w) acc[w] = fmaf(xr[w + j], wr[i * 7 + j], acc[w]);
      }
#pragma unroll
      for (int w = 0; w < WT; ++w) dsm[(r * WT + w) * (C + 1) + ch0 + tid] = acc[w];
    }
  }
  __syncthreads();

  const int nw = TB / 32, ntok = rows * WT;
  for (int tk = warp; tk < ntok; tk += nw) {
    const float* dr = dsm + tk * (C + 1);
    float s = 0.f;
    for (int c = lane; c < C; c += 32) s += dr[c];
    const float mean = warp_sum(s) / C;
    float v = 0.f;
    for (int c = lane; c < C; c += 32) { float d = dr[c] - mean; v += d * d; }
    const float rstd = rsqrtf(warp_sum(v) / C + p.eps);
    const int r = tk / WT, w = tk - r * WT;
    const size_t m = ((size_t)b * H + h0 + r) * W + w0 + w;
    __half* out = p.a1 + m * C;
    for (int pp = lane; pp < C / 2; pp += 32) {
      const int c = 2 * pp;
      float a0 = (dr[c] - mean) * rstd * __ldg(p.lnw + c) + __ldg(p.lnb + c);
      float a1 = (dr[c + 1] - mean) * rstd * __ldg(p.lnw + c + 1) + __ldg(p.lnb + c + 1);
      *reinterpret_cast<uint32_t*>(out + c) = pack_h2(a0, a1);
    }
  }
}

static __device__ __forceinline__ float gelu_erf(float z) {
  return 0.5f * z * (1.f + erff(z * 0.70710678118654752f));
}

// In-place bias + exact GELU on the fp16 GEMM1 output; per-(image, k) sum of squares into sumsq;
// writes the two ones-columns (4C, 4C+1) that carry b2' through GEMM2.
__global__ void k2_gelu(__half* Y, const float* b1, float* sumsq, int HW, int C, int LD, int tokb, int TS) {
  __shared__ float red[5120];
  const int K4 = 4 * C, V = C / 2, Vt = V + 1;
  const int kc = threadIdx.x % Vt, ts = threadIdx.x / Vt;
  const int b = blockIdx.y, t0 = blockIdx.x * tokb, tend = min(t0 + tokb, HW);
  __half* base = Y + (size_t)b * HW * LD;
  float acc[8];
#pragma unroll
  for (int i = 0; i < 8; ++i) acc[i] = 0.f;
  if (kc == V) {
    for (int t = t0 + ts; t < tend; t += TS)
      *reinterpret_cast<uint4*>(base + (size_t)t * LD + K4) = make_uint4(0x3C003C00u, 0u, 0u, 0u);
  } else {
    float bb[8];
    {
      float4 a = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8));
      float4 c = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8 + 4));
      bb[0] = a.x; bb[1] = a.y; bb[2] = a.z; bb[3] = a.w; bb[4] = c.x; bb[5] = c.y; bb[6] = c.z; bb[7] = c.w;
    }
    for (int t = t0 + ts; t < tend; t += 4 * TS) {
      uint4 v[4];
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) v[u] = *reinterpret_cast<const uint4*>(base + (size_t)tt * LD + kc * 8);
      }
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) {
          __half2* hp = reinterpret_cast<__half2*>(&v[u]);
          uint32_t o[4];
#pragma unroll
          for (int q = 0; q < 4; ++q) {
            float2 f = __half22float2(hp[q]);
            float g0 = gelu_erf(f.x + bb[2 * q]), g1 = gelu_erf(f.y + bb[2 * q + 1]);
            acc[2 * q] += g0 * g0;
            acc[2 * q + 1] += g1 * g1;
            o[q] = pack_h2(g0, g1);
          }
          *reinterpret_cast<uint4*>(base + (size_t)tt * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
        }
      }
    }
  }
  if (TS > 1 && kc < V && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
  if (kc < V && ts == 0) {
    for (int q = 1; q < TS; ++q) {
#pragma unroll
      for (int i = 0; i < 8; ++i) acc[i] += red[(q - 1) * K4 + kc * 8 + i];
    }
    float* dst = sumsq + (size_t)b * K4 + kc * 8;
    atomicAdd(reinterpret_cast<float4*>(dst), make_float4(acc[0], acc[1], acc[2], acc[3]));
    atomicAdd(reinterpret_cast<float4*>(dst + 4), make_float4(acc[4], acc[5], acc[6], acc[7]));
  }
}

// s[k] = 1 + gw[k] * gf[k] / (mean_k gf + eps), gf = sqrt(sumsq). 256 threads.
static __device__ void compute_s(float* s, float* red8, const float* ss, const float* gw, int K4, float eps) {
  const int tid = threadIdx.x;
  float loc = 0.f;
  for (int k = tid; k < K4; k += 256) { float g = sqrtf(ss[k]); s[k] = g; loc += g; }
  loc = warp_sum(loc);
  if ((tid & 31) == 0) red8[tid >> 5] = loc;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int i = 0; i < 8; ++i) tot += red8[i];
  const float inv = 1.f / (tot / K4 + eps);
  for (int k = tid; k < K4; k += 256) s[k] = 1.f + __ldg(gw + k) * s[k] * inv;
  __syncthreads();
}

// Branch A: per-image fp16 W2_b = W2 * diag(s_b), with b2' = b2 + W2 gb as hi/lo in columns 4C, 4C+1.
__global__ void __launch_bounds__(256) k3a_w2(const float* w2, const float* gb, const float* b2, const float* gw,
                                              const float* ss, __half* w2s, int C, int LD, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int lane = threadIdx.x & 31, c = blockIdx.x * 8 + (threadIdx.x >> 5);
  if (c >= C) return;
  const float* wr = w2 + (size_t)c * K4;
  __half* o = w2s + ((size_t)b * C + c) * LD;
  float dot = 0.f;
  for (int k = lane * 4; k < K4; k += 128) {
    float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
    float4 g = __ldg(reinterpret_cast<const float4*>(gb + k));
    float4 sv = *reinterpret_cast<const float4*>(sm + k);
    dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
    *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x * sv.x, w.y * sv.y), pack_h2(w.z * sv.z, w.w * sv.w));
  }
  dot = warp_sum(dot);
  const float bb = b2[c] + dot;
  if (lane < 8) {
    __half hi = __float2half_rn(bb);
    __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
    o[K4 + lane] = v;
  }
}

// Branch B: scale the hidden rows in place (columns < 4C), fp16.
__global__ void __launch_bounds__(256) k3b_scale(__half* Y, const float* gw, const float* ss, int HW, int C, int LD,
                                                 int tokb, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, V = C / 2, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int t0 = blockIdx.x * tokb, ntok = min(tokb, HW - t0);
  __half* base = Y + ((size_t)b * HW + t0) * LD;
  const int total = ntok * V;
  for (int i0 = threadIdx.x; i0 < total; i0 += 1024) {
    uint4 v[4];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        v[u] = *reinterpret_cast<const uint4*>(base + (size_t)t * LD + kc * 8);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        __half2* hp = reinterpret_cast<__half2*>(&v[u]);
        uint32_t o[4];
#pragma unroll
        for (int q = 0; q < 4; ++q) {
          float2 f = __half22float2(hp[q]);
          o[q] = pack_h2(f.x * sm[kc * 8 + 2 * q], f.y * sm[kc * 8 + 2 * q + 1]);
        }
        *reinterpret_cast<uint4*>(base + (size_t)t * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
      }
    }
  }
}

// ------------------------------------------------------------------ host side
static const size_t kCublasWs = 32u << 20;

struct Plan {
  int B, C, H, W, M, HW, K4, LD;
  bool bB;
  int WT, TB, RT, nTW, nTH, ntiles, nrole, PS;
  size_t smem1;
  int tokb, TS2, thr2;
  size_t off_a1, off_y, off_w1h, off_w2h, off_ss, off_cw, total;
  cublasLtMatmulDesc_t md1, md2;
  cublasLtMatrixLayout_t la1, lb1, ld1, la2, lb2, lc2;
  cublasLtMatmulHeuristicResult_t h1[8], h2[8];
  int n1, n2;
};

static cublasLtHandle_t g_lt = nullptr;
static std::map<uint64_t, Plan*> g_plans;
static int g_idx1 = 0, g_idx2 = 0;

extern "C" void convblk_set_idx(int a, int b) { g_idx1 = a; g_idx2 = b; }

static size_t al256(size_t x) { return (x + 255) & ~(size_t)255; }

static cublasStatus_t mk_layout(cublasLtMatrixLayout_t* l, cudaDataType t, uint64_t rows, uint64_t cols, int64_t ld,
                                int batch, int64_t stride) {
  cublasStatus_t s = cublasLtMatrixLayoutCreate(l, t, rows, cols, ld);
  if (s != CUBLAS_STATUS_SUCCESS) return s;
  if (batch > 1) {
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &batch, sizeof(batch));
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &stride, sizeof(stride));
  }
  return s;
}

static int heur(cublasLtMatmulDesc_t md, cublasLtMatrixLayout_t a, cublasLtMatrixLayout_t b, cublasLtMatrixLayout_t c,
                uint32_t alA, uint32_t alB, uint32_t alC, cublasLtMatmulHeuristicResult_t* out, int* n) {
  cublasLtMatmulPreference_t pref;
  CB(cublasLtMatmulPreferenceCreate(&pref));
  size_t wsb = kCublasWs;
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsb, sizeof(wsb));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &alA, sizeof(alA));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &alB, sizeof(alB));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &alC, sizeof(alC));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &alC, sizeof(alC));
  int cnt = 0;
  cublasStatus_t s = cublasLtMatmulAlgoGetHeuristic(g_lt, md, a, b, c, c, pref, 8, out, &cnt);
  cublasLtMatmulPreferenceDestroy(pref);
  CB(s);
  if (cnt == 0) return 300;
  *n = cnt;
  return 0;
}

static int make_plan(Plan* P, int B, int C, int H, int W) {
  P->B = B; P->C = C; P->H = H; P->W = W;
  P->HW = H * W; P->M = B * P->HW; P->K4 = 4 * C; P->LD = P->K4 + 8;
  const int M = P->M, HW = P->HW, K4 = P->K4, LD = P->LD;
  P->bB = (size_t)B * C * LD * 2 > ((size_t)16 << 20);
  P->WT = (W % 16 == 0) ? 16 : (W % 14 == 0) ? 14 : (W % 7 == 0) ? 7 : 0;
  if (!P->WT || (C % 32)) return 1;
  int tb = std::min(C, 192) / 32 * 32;
  while (tb >= 32 && C % tb) tb -= 32;
  if (tb < 32) return 2;
  P->TB = tb;
  P->nTW = W / P->WT;
  auto smem_of = [&](int rt) {
    int ps = ((rt + 6) * (P->WT + 6)) | 1;
    return (size_t)4 * ((size_t)tb * ps + (size_t)tb * 49 + (size_t)rt * P->WT * (C + 1));
  };
  int rt = 1;
  for (int r = 1; r <= std::min(H, 8); ++r) {
    int tiles = B * ((H + r - 1) / r) * P->nTW;
    if (smem_of(r) <= 110000 && tiles >= 296) rt = r;
  }
  P->RT = rt;
  P->PS = ((rt + 6) * (P->WT + 6)) | 1;
  P->smem1 = smem_of(rt);
  if (P->smem1 > 227000) return 3;
  P->nTH = (H + rt - 1) / rt;
  P->ntiles = B * P->nTH * P->nTW;
  P->nrole = std::max(64, std::min(128, 148 - P->ntiles));
  if (P->WT == 7) CK(cudaFuncSetAttribute(k1_dwln<7>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 14) CK(cudaFuncSetAttribute(k1_dwln<14>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 16) CK(cudaFuncSetAttribute(k1_dwln<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  int tokb = 4;
  while (tokb * 2 <= 256 && (int64_t)M / (tokb * 2) >= 592) tokb *= 2;
  P->tokb = tokb;
  const int Vt = C / 2 + 1;
  P->TS2 = std::min(4, 1024 / Vt);
  P->thr2 = Vt * P->TS2;
  CK(cudaFuncSetAttribute(k3a_w2, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));
  CK(cudaFuncSetAttribute(k3b_scale, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));

  P->off_a1 = 0;
  P->off_y = al256((size_t)M * C * 2);
  P->off_w1h = P->off_y + al256((size_t)M * LD * 2);
  P->off_w2h = P->off_w1h + al256((size_t)K4 * C * 2);
  P->off_ss = P->off_w2h + al256((size_t)(P->bB ? 1 : B) * C * LD * 2);
  P->off_cw = P->off_ss + al256((size_t)B * K4 * 4);
  P->total = P->off_cw + kCublasWs;

  if (!g_lt) CB(cublasLtCreate(&g_lt));
  cublasOperation_t opT = CUBLAS_OP_T, opN = CUBLAS_OP_N;
  CB(cublasLtMatmulDescCreate(&P->md1, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la1, CUDA_R_16F, C, K4, C, 1, 0));
  CB(mk_layout(&P->lb1, CUDA_R_16F, C, M, C, 1, 0));
  CB(mk_layout(&P->ld1, CUDA_R_16F, K4, M, LD, 1, 0));
  int rc = heur(P->md1, P->la1, P->lb1, P->ld1, 16, 16, 16, P->h1, &P->n1);
  if (rc) return rc;

  CB(cublasLtMatmulDescCreate(&P->md2, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la2, CUDA_R_16F, LD, HW, LD, B, (int64_t)HW * LD));
  CB(mk_layout(&P->lb2, CUDA_R_16F, LD, C, LD, B, P->bB ? 0 : (int64_t)C * LD));
  CB(mk_layout(&P->lc2, CUDA_R_32F, HW, C, HW, B, (int64_t)C * HW));
  rc = heur(P->md2, P->la2, P->lb2, P->lc2, 16, 16, (HW % 4 == 0) ? 16 : 4, P->h2, &P->n2);
  return rc;
}

static Plan* get_plan(int B, int C, int H, int W, int* err) {
  uint64_t key = ((uint64_t)B << 48) ^ ((uint64_t)C << 32) ^ ((uint64_t)H << 16) ^ (uint64_t)W;
  auto it = g_plans.find(key);
  if (it != g_plans.end()) return it->second;
  Plan* P = new Plan();
  int rc = make_plan(P, B, C, H, W);
  if (rc) { *err = rc; delete P; return nullptr; }
  g_plans[key] = P;
  return P;
}

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  return P ? P->total : 0;
}

extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* wsp, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st) {
  int err = 0;
  Plan* P = get_plan(B, C, H, W, &err);
  if (!P) return err;
  char* ws = static_cast<char*>(wsp);
  __half* a1 = reinterpret_cast<__half*>(ws + P->off_a1);
  __half* y = reinterpret_cast<__half*>(ws + P->off_y);
  __half* w1h = reinterpret_cast<__half*>(ws + P->off_w1h);
  __half* w2h = reinterpret_cast<__half*>(ws + P->off_w2h);
  float* ss = reinterpret_cast<float*>(ws + P->off_ss);
  void* cw = ws + P->off_cw;

  K1P k;
  k.x = x; k.dww = dww; k.dwb = dwb; k.lnw = lnw; k.lnb = lnb; k.w1 = w1; k.gb = gb; k.w2 = w2; k.b2 = b2;
  k.a1 = a1; k.w1h = w1h; k.w2h = w2h; k.sumsq = ss;
  k.B = B; k.C = C; k.H = H; k.W = W; k.RT = P->RT; k.TB = P->TB; k.nTW = P->nTW; k.nTH = P->nTH;
  k.nrole = P->nrole; k.LD = P->LD; k.doW2 = P->bB ? 1 : 0; k.PS = P->PS; k.eps = ln_eps;
  const int g1 = P->nrole + P->ntiles;
  if (P->WT == 7) k1_dwln<7><<<g1, P->TB, P->smem1, st>>>(k);
  else if (P->WT == 14) k1_dwln<14><<<g1, P->TB, P->smem1, st>>>(k);
  else k1_dwln<16><<<g1, P->TB, P->smem1, st>>>(k);
  CK(cudaGetLastError());

  const float alpha = 1.f, beta0 = 0.f, beta1 = 1.f;
  const int i1 = std::min(g_idx1, P->n1 - 1), i2 = std::min(g_idx2, P->n2 - 1);
  CB(cublasLtMatmul(g_lt, P->md1, &alpha, w1h, P->la1, a1, P->lb1, &beta0, y, P->ld1, y, P->ld1, &P->h1[i1].algo, cw,
                    kCublasWs, st));

  const int nb = (P->HW + P->tokb - 1) / P->tokb;
  k2_gelu<<<dim3(nb, B), P->thr2, 0, st>>>(y, b1, ss, P->HW, C, P->LD, P->tokb, P->TS2);
  CK(cudaGetLastError());
  if (P->bB) {
    k3b_scale<<<dim3(nb, B), 256, 4 * P->K4 + 64, st>>>(y, gw, ss, P->HW, C, P->LD, P->tokb, grn_eps);
  } else {
    k3a_w2<<<dim3((C + 7) / 8, B), 256, 4 * P->K4 + 64, st>>>(w2, gb, b2, gw, ss, w2h, C, P->LD, grn_eps);
  }
  CK(cudaGetLastError());

  CB(cublasLtMatmul(g_lt, P->md2, &alpha, y, P->la2, w2h, P->lb2, &beta1, x, P->lc2, out, P->lc2, &P->h2[i2].algo, cw,
                    kCublasWs, st));
  return 0;
}

#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

extern "C" size_t convblk_ws_bytes(int B, int C, int H, int W);
extern "C" int convblk_run(const float* x, const float* dww, const float* dwb, const float* lnw, const float* lnb,
                           const float* w1, const float* b1, const float* gw, const float* gb, const float* w2,
                           const float* b2, float* out, void* ws, int B, int C, int H, int W, float grn_eps,
                           float ln_eps, cudaStream_t st);

void run(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb,
         torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2,
         double eps, double ln_eps, torch::Tensor out) {
  c10::cuda::CUDAGuard guard(x.device());
  TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32 && x.is_contiguous(), "x must be contiguous fp32 cuda");
  const int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
  size_t wb = convblk_ws_bytes(B, C, H, W);
  TORCH_CHECK(wb > 0, "unsupported shape or cuBLASLt heuristic failure");
  auto ws = torch::empty({(int64_t)wb}, x.options().dtype(torch::kUInt8));
  cudaStream_t st = c10::cuda::getCurrentCUDAStream();
  int rc = convblk_run(x.data_ptr<float>(), dww.data_ptr<float>(), dwb.data_ptr<float>(), lnw.data_ptr<float>(),
                       lnb.data_ptr<float>(), w1.data_ptr<float>(), b1.data_ptr<float>(), gw.data_ptr<float>(),
                       gb.data_ptr<float>(), w2.data_ptr<float>(), b2.data_ptr<float>(), out.data_ptr<float>(),
                       ws.data_ptr(), B, C, H, W, (float)eps, (float)ln_eps, st);
  TORCH_CHECK(rc == 0, "convblk_run failed with code ", rc);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "convnextv2 block"); }

#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <algorithm>

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) return 100 + (int)e_; } while (0)
#define CB(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) return 200 + (int)s_; } while (0)

static __device__ __forceinline__ uint32_t pack_h2(float a, float b) {
  __half2 h = __floats2half2_rn(a, b);
  return *reinterpret_cast<uint32_t*>(&h);
}
static __device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

struct K1P {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *gb, *w2, *b2;
  __half *a1, *w1h, *w2h;
  float* sumsq;
  int B, C, H, W, RT, TB, nTW, nTH, nrole, LD, doW2, PS;
  float eps;
};

// Extra blocks of K1: zero the GRN workspace, convert W1 (and W2 + b2' for the scale-h branch) to fp16.
static __device__ void k1_role(const K1P& p, int rb, int tid, int nthr) {
  const int gtid = rb * nthr + tid, gn = p.nrole * nthr;
  const int K4 = 4 * p.C;
  for (int i = gtid; i < p.B * K4; i += gn) p.sumsq[i] = 0.f;
  const long n8 = (long)K4 * p.C / 8;
  for (long i0 = gtid; i0 < n8; i0 += 4L * gn) {
    float4 v[4][2];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      v[u][0] = v[u][1] = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < n8) {
        const float4* s = reinterpret_cast<const float4*>(p.w1 + i * 8);
        v[u][0] = __ldg(s);
        v[u][1] = __ldg(s + 1);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      if (i < n8) {
        uint4 o = make_uint4(pack_h2(v[u][0].x, v[u][0].y), pack_h2(v[u][0].z, v[u][0].w),
                             pack_h2(v[u][1].x, v[u][1].y), pack_h2(v[u][1].z, v[u][1].w));
        *reinterpret_cast<uint4*>(p.w1h + i * 8) = o;
      }
    }
  }
  if (p.doW2) {
    const int nw = nthr / 32, lane = tid & 31;
    const int gw_ = rb * nw + (tid >> 5), gnw = p.nrole * nw;
    for (int c = gw_; c < p.C; c += gnw) {
      const float* wr = p.w2 + (size_t)c * K4;
      __half* o = p.w2h + (size_t)c * p.LD;
      float dot = 0.f;
      for (int k = lane * 4; k < K4; k += 128) {
        float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
        float4 g = __ldg(reinterpret_cast<const float4*>(p.gb + k));
        dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
        *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x, w.y), pack_h2(w.z, w.w));
      }
      dot = warp_sum(dot);
      const float bb = p.b2[c] + dot;
      if (lane < 8) {
        __half hi = __float2half_rn(bb);
        __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
        o[K4 + lane] = v;
      }
    }
  }
}

// Fused depthwise 7x7 conv + bias + LayerNorm. Lane = channel; a tile of RT rows x WT columns of one image
// and all channels per block. Channel chunks of TB planes are staged in shared memory with cp.async.
template <int WT>
__global__ void __launch_bounds__(192) k1_dwln(const K1P p) {
  extern __shared__ float sm[];
  const int tid = threadIdx.x, TB = p.TB;
  if ((int)blockIdx.x < p.nrole) { k1_role(p, blockIdx.x, tid, TB); return; }
  int t = blockIdx.x - p.nrole;
  const int tw = t % p.nTW; t /= p.nTW;
  const int th = t % p.nTH;
  const int b = t / p.nTH;
  const int C = p.C, H = p.H, W = p.W, RT = p.RT, PS = p.PS;
  const int h0 = th * RT, w0 = tw * WT;
  const int rows = min(RT, H - h0);
  constexpr int CW = WT + 6;
  const int RG = (RT + 6) * CW;
  float* pl = sm;
  float* wsm = sm + TB * PS;
  float* dsm = wsm + TB * 49;
  const int lane = tid & 31, warp = tid >> 5;

  for (int ch0 = 0; ch0 < C; ch0 += TB) {
    __syncthreads();
    for (int cl = warp * 32; cl < warp * 32 + 32; ++cl) {
      const float* xp = p.x + (size_t)(b * C + ch0 + cl) * H * W;
      float* dp = pl + cl * PS;
      for (int rem = lane; rem < RG; rem += 32) {
        const int rr = rem / CW, cc = rem - rr * CW;
        const int gh = h0 - 3 + rr, gw = w0 - 3 + cc;
        const bool ok = gh >= 0 && gh < H && gw >= 0 && gw < W;
        const float* src = ok ? xp + gh * W + gw : p.x;
        uint32_t d = (uint32_t)__cvta_generic_to_shared(dp + rem);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;" :: "r"(d), "l"(src), "r"(ok ? 4 : 0));
      }
    }
    for (int e = tid; e < TB * 49; e += TB) {
      uint32_t d = (uint32_t)__cvta_generic_to_shared(wsm + e);
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4;" :: "r"(d), "l"(p.dww + (size_t)ch0 * 49 + e));
    }
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
    __syncthreads();

    float wr[49];
    const float* wp = wsm + tid * 49;
#pragma unroll
    for (int k = 0; k < 49; ++k) wr[k] = wp[k];
    const float bias = __ldg(p.dwb + ch0 + tid);
    const float* pt = pl + tid * PS;
    for (int r = 0; r < rows; ++r) {
      float acc[WT];
#pragma unroll
      for (int w = 0; w < WT; ++w) acc[w] = bias;
#pragma unroll
      for (int i = 0; i < 7; ++i) {
        float xr[CW];
#pragma unroll
        for (int q = 0; q < CW; ++q) xr[q] = pt[(r + i) * CW + q];
#pragma unroll
        for (int j = 0; j < 7; ++j)
#pragma unroll
          for (int w = 0; w < WT; ++w) acc[w] = fmaf(xr[w + j], wr[i * 7 + j], acc[w]);
      }
#pragma unroll
      for (int w = 0; w < WT; ++w) dsm[(r * WT + w) * (C + 1) + ch0 + tid] = acc[w];
    }
  }
  __syncthreads();

  const int nw = TB / 32, ntok = rows * WT;
  for (int tk = warp; tk < ntok; tk += nw) {
    const float* dr = dsm + tk * (C + 1);
    float s = 0.f;
    for (int c = lane; c < C; c += 32) s += dr[c];
    const float mean = warp_sum(s) / C;
    float v = 0.f;
    for (int c = lane; c < C; c += 32) { float d = dr[c] - mean; v += d * d; }
    const float rstd = rsqrtf(warp_sum(v) / C + p.eps);
    const int r = tk / WT, w = tk - r * WT;
    const size_t m = ((size_t)b * H + h0 + r) * W + w0 + w;
    __half* out = p.a1 + m * C;
    for (int pp = lane; pp < C / 2; pp += 32) {
      const int c = 2 * pp;
      float a0 = (dr[c] - mean) * rstd * __ldg(p.lnw + c) + __ldg(p.lnb + c);
      float a1 = (dr[c + 1] - mean) * rstd * __ldg(p.lnw + c + 1) + __ldg(p.lnb + c + 1);
      *reinterpret_cast<uint32_t*>(out + c) = pack_h2(a0, a1);
    }
  }
}

static __device__ __forceinline__ float gelu_erf(float z) {
  return 0.5f * z * (1.f + erff(z * 0.70710678118654752f));
}

// In-place bias + exact GELU on the fp16 GEMM1 output; per-(image, k) sum of squares into sumsq;
// writes the two ones-columns (4C, 4C+1) that carry b2' through GEMM2.
__global__ void k2_gelu(__half* Y, const float* b1, float* sumsq, int HW, int C, int LD, int tokb, int TS) {
  __shared__ float red[5120];
  const int K4 = 4 * C, V = C / 2, Vt = V + 1;
  const int kc = threadIdx.x % Vt, ts = threadIdx.x / Vt;
  const int b = blockIdx.y, t0 = blockIdx.x * tokb, tend = min(t0 + tokb, HW);
  __half* base = Y + (size_t)b * HW * LD;
  float acc[8];
#pragma unroll
  for (int i = 0; i < 8; ++i) acc[i] = 0.f;
  if (kc == V) {
    for (int t = t0 + ts; t < tend; t += TS)
      *reinterpret_cast<uint4*>(base + (size_t)t * LD + K4) = make_uint4(0x3C003C00u, 0u, 0u, 0u);
  } else {
    float bb[8];
    {
      float4 a = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8));
      float4 c = __ldg(reinterpret_cast<const float4*>(b1 + kc * 8 + 4));
      bb[0] = a.x; bb[1] = a.y; bb[2] = a.z; bb[3] = a.w; bb[4] = c.x; bb[5] = c.y; bb[6] = c.z; bb[7] = c.w;
    }
    for (int t = t0 + ts; t < tend; t += 4 * TS) {
      uint4 v[4];
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) v[u] = *reinterpret_cast<const uint4*>(base + (size_t)tt * LD + kc * 8);
      }
#pragma unroll
      for (int u = 0; u < 4; ++u) {
        const int tt = t + u * TS;
        if (tt < tend) {
          __half2* hp = reinterpret_cast<__half2*>(&v[u]);
          uint32_t o[4];
#pragma unroll
          for (int q = 0; q < 4; ++q) {
            float2 f = __half22float2(hp[q]);
            float g0 = gelu_erf(f.x + bb[2 * q]), g1 = gelu_erf(f.y + bb[2 * q + 1]);
            acc[2 * q] += g0 * g0;
            acc[2 * q + 1] += g1 * g1;
            o[q] = pack_h2(g0, g1);
          }
          *reinterpret_cast<uint4*>(base + (size_t)tt * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
        }
      }
    }
  }
  if (TS > 1 && kc < V && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
  if (kc < V && ts == 0) {
    for (int q = 1; q < TS; ++q) {
#pragma unroll
      for (int i = 0; i < 8; ++i) acc[i] += red[(q - 1) * K4 + kc * 8 + i];
    }
    float* dst = sumsq + (size_t)b * K4 + kc * 8;
    atomicAdd(reinterpret_cast<float4*>(dst), make_float4(acc[0], acc[1], acc[2], acc[3]));
    atomicAdd(reinterpret_cast<float4*>(dst + 4), make_float4(acc[4], acc[5], acc[6], acc[7]));
  }
}

// s[k] = 1 + gw[k] * gf[k] / (mean_k gf + eps), gf = sqrt(sumsq). 256 threads.
static __device__ void compute_s(float* s, float* red8, const float* ss, const float* gw, int K4, float eps) {
  const int tid = threadIdx.x;
  float loc = 0.f;
  for (int k = tid; k < K4; k += 256) { float g = sqrtf(ss[k]); s[k] = g; loc += g; }
  loc = warp_sum(loc);
  if ((tid & 31) == 0) red8[tid >> 5] = loc;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int i = 0; i < 8; ++i) tot += red8[i];
  const float inv = 1.f / (tot / K4 + eps);
  for (int k = tid; k < K4; k += 256) s[k] = 1.f + __ldg(gw + k) * s[k] * inv;
  __syncthreads();
}

// Branch A: per-image fp16 W2_b = W2 * diag(s_b), with b2' = b2 + W2 gb as hi/lo in columns 4C, 4C+1.
__global__ void __launch_bounds__(256) k3a_w2(const float* w2, const float* gb, const float* b2, const float* gw,
                                              const float* ss, __half* w2s, int C, int LD, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int lane = threadIdx.x & 31, c = blockIdx.x * 8 + (threadIdx.x >> 5);
  if (c >= C) return;
  const float* wr = w2 + (size_t)c * K4;
  __half* o = w2s + ((size_t)b * C + c) * LD;
  float dot = 0.f;
  for (int k = lane * 4; k < K4; k += 128) {
    float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
    float4 g = __ldg(reinterpret_cast<const float4*>(gb + k));
    float4 sv = *reinterpret_cast<const float4*>(sm + k);
    dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
    *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x * sv.x, w.y * sv.y), pack_h2(w.z * sv.z, w.w * sv.w));
  }
  dot = warp_sum(dot);
  const float bb = b2[c] + dot;
  if (lane < 8) {
    __half hi = __float2half_rn(bb);
    __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
    o[K4 + lane] = v;
  }
}

// Branch B: scale the hidden rows in place (columns < 4C), fp16.
__global__ void __launch_bounds__(256) k3b_scale(__half* Y, const float* gw, const float* ss, int HW, int C, int LD,
                                                 int tokb, float eps) {
  extern __shared__ float sm[];
  const int K4 = 4 * C, V = C / 2, b = blockIdx.y;
  compute_s(sm, sm + K4, ss + (size_t)b * K4, gw, K4, eps);
  const int t0 = blockIdx.x * tokb, ntok = min(tokb, HW - t0);
  __half* base = Y + ((size_t)b * HW + t0) * LD;
  const int total = ntok * V;
  for (int i0 = threadIdx.x; i0 < total; i0 += 1024) {
    uint4 v[4];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        v[u] = *reinterpret_cast<const uint4*>(base + (size_t)t * LD + kc * 8);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      const int i = i0 + u * 256;
      if (i < total) {
        const int t = i / V, kc = i - t * V;
        __half2* hp = reinterpret_cast<__half2*>(&v[u]);
        uint32_t o[4];
#pragma unroll
        for (int q = 0; q < 4; ++q) {
          float2 f = __half22float2(hp[q]);
          o[q] = pack_h2(f.x * sm[kc * 8 + 2 * q], f.y * sm[kc * 8 + 2 * q + 1]);
        }
        *reinterpret_cast<uint4*>(base + (size_t)t * LD + kc * 8) = make_uint4(o[0], o[1], o[2], o[3]);
      }
    }
  }
}

// ------------------------------------------------------------------ host side
static const size_t kCublasWs = 32u << 20;

struct Plan {
  int B, C, H, W, M, HW, K4, LD;
  bool bB;
  int WT, TB, RT, nTW, nTH, ntiles, nrole, PS;
  size_t smem1;
  int tokb, TS2, thr2;
  size_t off_a1, off_y, off_w1h, off_w2h, off_ss, off_cw, total;
  cublasLtMatmulDesc_t md1, md2;
  cublasLtMatrixLayout_t la1, lb1, ld1, la2, lb2, lc2;
  cublasLtMatmulHeuristicResult_t h1[8], h2[8];
  int n1, n2;
};

static cublasLtHandle_t g_lt = nullptr;
static std::map<uint64_t, Plan*> g_plans;
static int g_idx1 = 0, g_idx2 = 0;

extern "C" void convblk_set_idx(int a, int b) { g_idx1 = a; g_idx2 = b; }

static size_t al256(size_t x) { return (x + 255) & ~(size_t)255; }

static cublasStatus_t mk_layout(cublasLtMatrixLayout_t* l, cudaDataType t, uint64_t rows, uint64_t cols, int64_t ld,
                                int batch, int64_t stride) {
  cublasStatus_t s = cublasLtMatrixLayoutCreate(l, t, rows, cols, ld);
  if (s != CUBLAS_STATUS_SUCCESS) return s;
  if (batch > 1) {
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &batch, sizeof(batch));
    cublasLtMatrixLayoutSetAttribute(*l, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &stride, sizeof(stride));
  }
  return s;
}

static int heur(cublasLtMatmulDesc_t md, cublasLtMatrixLayout_t a, cublasLtMatrixLayout_t b, cublasLtMatrixLayout_t c,
                uint32_t alA, uint32_t alB, uint32_t alC, cublasLtMatmulHeuristicResult_t* out, int* n) {
  cublasLtMatmulPreference_t pref;
  CB(cublasLtMatmulPreferenceCreate(&pref));
  size_t wsb = kCublasWs;
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsb, sizeof(wsb));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &alA, sizeof(alA));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &alB, sizeof(alB));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &alC, sizeof(alC));
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &alC, sizeof(alC));
  int cnt = 0;
  cublasStatus_t s = cublasLtMatmulAlgoGetHeuristic(g_lt, md, a, b, c, c, pref, 8, out, &cnt);
  cublasLtMatmulPreferenceDestroy(pref);
  CB(s);
  if (cnt == 0) return 300;
  *n = cnt;
  return 0;
}

static int make_plan(Plan* P, int B, int C, int H, int W) {
  P->B = B; P->C = C; P->H = H; P->W = W;
  P->HW = H * W; P->M = B * P->HW; P->K4 = 4 * C; P->LD = P->K4 + 8;
  const int M = P->M, HW = P->HW, K4 = P->K4, LD = P->LD;
  P->bB = (size_t)B * C * LD * 2 > ((size_t)16 << 20);
  P->WT = (W % 16 == 0) ? 16 : (W % 14 == 0) ? 14 : (W % 7 == 0) ? 7 : 0;
  if (!P->WT || (C % 32)) return 1;
  int tb = std::min(C, 192) / 32 * 32;
  while (tb >= 32 && C % tb) tb -= 32;
  if (tb < 32) return 2;
  P->TB = tb;
  P->nTW = W / P->WT;
  auto smem_of = [&](int rt) {
    int ps = ((rt + 6) * (P->WT + 6)) | 1;
    return (size_t)4 * ((size_t)tb * ps + (size_t)tb * 49 + (size_t)rt * P->WT * (C + 1));
  };
  int rt = 1;
  for (int r = 1; r <= std::min(H, 8); ++r) {
    int tiles = B * ((H + r - 1) / r) * P->nTW;
    if (smem_of(r) <= 110000 && tiles >= 296) rt = r;
  }
  P->RT = rt;
  P->PS = ((rt + 6) * (P->WT + 6)) | 1;
  P->smem1 = smem_of(rt);
  if (P->smem1 > 227000) return 3;
  P->nTH = (H + rt - 1) / rt;
  P->ntiles = B * P->nTH * P->nTW;
  P->nrole = std::max(64, std::min(128, 148 - P->ntiles));
  if (P->WT == 7) CK(cudaFuncSetAttribute(k1_dwln<7>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 14) CK(cudaFuncSetAttribute(k1_dwln<14>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 16) CK(cudaFuncSetAttribute(k1_dwln<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  int tokb = 4;
  while (tokb * 2 <= 256 && (int64_t)M / (tokb * 2) >= 592) tokb *= 2;
  P->tokb = tokb;
  const int Vt = C / 2 + 1;
  P->TS2 = std::min(4, 1024 / Vt);
  P->thr2 = Vt * P->TS2;
  CK(cudaFuncSetAttribute(k3a_w2, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));
  CK(cudaFuncSetAttribute(k3b_scale, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * K4 + 64));

  P->off_a1 = 0;
  P->off_y = al256((size_t)M * C * 2);
  P->off_w1h = P->off_y + al256((size_t)M * LD * 2);
  P->off_w2h = P->off_w1h + al256((size_t)K4 * C * 2);
  P->off_ss = P->off_w2h + al256((size_t)(P->bB ? 1 : B) * C * LD * 2);
  P->off_cw = P->off_ss + al256((size_t)B * K4 * 4);
  P->total = P->off_cw + kCublasWs;

  if (!g_lt) CB(cublasLtCreate(&g_lt));
  cublasOperation_t opT = CUBLAS_OP_T, opN = CUBLAS_OP_N;
  CB(cublasLtMatmulDescCreate(&P->md1, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md1, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la1, CUDA_R_16F, C, K4, C, 1, 0));
  CB(mk_layout(&P->lb1, CUDA_R_16F, C, M, C, 1, 0));
  CB(mk_layout(&P->ld1, CUDA_R_16F, K4, M, LD, 1, 0));
  int rc = heur(P->md1, P->la1, P->lb1, P->ld1, 16, 16, 16, P->h1, &P->n1);
  if (rc) return rc;

  CB(cublasLtMatmulDescCreate(&P->md2, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSA, &opT, sizeof(opT)));
  CB(cublasLtMatmulDescSetAttribute(P->md2, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN)));
  CB(mk_layout(&P->la2, CUDA_R_16F, LD, HW, LD, B, (int64_t)HW * LD));
  CB(mk_layout(&P->lb2, CUDA_R_16F, LD, C, LD, B, P->bB ? 0 : (int64_t)C * LD));
  CB(mk_layout(&P->lc2, CUDA_R_32F, HW, C, HW, B, (int64_t)C * HW));
