    tile[ty + 8 * j][tx] = (hw < HW && c < C) ? d2[((size_t)b * HW + hw) * C + c] : 0.f;
  }
  __syncthreads();
#pragma unroll
  for (int j = 0; j < 4; ++j) {
    const int c = c0 + ty + 8 * j, hw = hw0 + tx;
    if (hw < HW && c < C) { const size_t i = ((size_t)b * C + c) * HW + hw; out[i] = x[i] + tile[tx][ty + 8 * j]; }
