static int make_plan(Plan* P, int B, int C, int H, int W) {
  P->B = B; P->C = C; P->H = H; P->W = W;
  P->HW = H * W; P->M = B * P->HW; P->K4 = 4 * C; P->LD = P->K4 + 8;
  const int M = P->M, HW = P->HW, K4 = P->K4, LD = P->LD;
