  if (P->WT == 14) CK(cudaFuncSetAttribute(k1_dw<14>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  if (P->WT == 16) CK(cudaFuncSetAttribute(k1_dw<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)P->smem1));
  int tokb = 4;
