  auto it = g_plans.find(key);
  if (it != g_plans.end()) return it->second;
  Plan* P = new Plan();
  int rc = make_plan(P, B, C, H, W);
  if (rc) { *err = rc; delete P; return nullptr; }
  g_plans[key] = P;
  return P;
}
extern "C" void convblk_counts(int B, int C, int H, int W, int* o) {
  int err = 0; Plan* P = get_plan(B, C, H, W, &err);
  if (!P) { o[0] = -err; return; }
  o[0] = P->n1; o[1] = P->n2; o[2] = P->RT; o[3] = P->NWc; o[4] = P->ntiles; o[5] = P->nrole; o[6] = P->bB; o[7] = P->useCL;
