  if (P->bB) k3b_scale<<<dim3(nb, B), 256, 4 * P->K4 + 64, st>>>(y, gw, ss, P->HW, C, P->LD, P->tokb, grn_eps);
  else k3a_w2<<<dim3((C + 7) / 8, B), 256, 4 * P->K4 + 64, st>>>(w2, gb, b2, gw, ss, w2h, C, P->LD, grn_eps);
